shellCommands.command:
npx tsc --noEmit; echo "TSC_EXIT=$?"; cat > src/smoke.tmp.test.tsx <<'EOF'
import {renderToString} from 'react-dom/server';
import {test, expect} from 'vitest';
import {App} from './App';

test('landing renders hero, three benefits and one CTA', () => {
  const html = renderToString(<App />);
  const text = html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
  console.log(text);
  for (const s of ['Все часы команды', 'Учёт в один клик', 'Видно загрузку команды', 'Отчёты без ручной сверки', 'Начните вести учёт времени сегодня', 'Начать работу']) {
    expect(text).toContain(s);
  }
  expect(html.match(/<button|<a /g)?.length ?? 0).toBeGreaterThan(0);
  console.log('BUTTON_OR_LINK_COUNT', (html.match(/<a |<button/g) || []).length);
});
EOF
timeout 170 npx vitest run src/smoke.tmp.test.tsx 2>&1 | tail -40; rm -f src/smoke.tmp.test.tsx; ls src

